			this.args = Collections.emptyList();
		} else {
			this.args = new ArrayList<>(c.args);
		}
	}

	public static IfCondition fromIfBlock(BlockNode header) {
		InsnNode lastInsn = BlockUtils.getLastInsn(header);
		if (lastInsn == null) {
