			IfCondition arg = cond.getArgs().get(i);
			IfCondition simpl = simplify(arg);
			if (simpl != arg) {
				if (args == null) {
					args = new ArrayList<>(cond.getArgs());
				}
				args.set(i, simpl);
			}
		}
